import type { BillingAddress } from '@proton/payments';
import {
    type Currency,
    type FreeSubscription,
    PLANS,
    type PlanIDs,
    isFreeSubscription,
    isRegionalCurrency,
} from '@proton/payments';
import type { ProductParam } from '@proton/shared/lib/apps/product';
import { APPS, COUPON_CODES, CYCLE, VPN_PASS_PROMOTION_COUPONS } from '@proton/shared/lib/constants';
import { getPlanFromIDs } from '@proton/shared/lib/helpers/planIDs';
import type { PlansMap, SubscriptionModel } from '@proton/shared/lib/interfaces';
import { Audience, Renew } from '@proton/shared/lib/interfaces';

export const getVPNPlanToUse = ({
    planIDs,
}: {
    plansMap: PlansMap;
    planIDs: PlanIDs | undefined;
    cycle: CYCLE | undefined;
}) => {
    // If the user is on the vpn2022 plan, we keep showing that
    if (planIDs?.[PLANS.VPN]) {
        return PLANS.VPN;
    }
    return PLANS.VPN2024;
};

export const getBundleProPlanToUse = ({ plansMap, planIDs }: { plansMap: PlansMap; planIDs: PlanIDs | undefined }) => {
    // If the user is on the bundlepro2022 plan, we keep showing that
    if (planIDs?.[PLANS.BUNDLE_PRO]) {
        return PLANS.BUNDLE_PRO;
    }
    if (plansMap[PLANS.BUNDLE_PRO_2024]) {
        return PLANS.BUNDLE_PRO_2024;
    }
    if (plansMap[PLANS.BUNDLE_PRO]) {
        return PLANS.BUNDLE_PRO;
    }
    return PLANS.BUNDLE_PRO_2024;
};

export const getIsVPNPassPromotion = (coupon: string | undefined, currency: Currency | undefined) => {
    return VPN_PASS_PROMOTION_COUPONS.includes(coupon as any) && (!currency || !isRegionalCurrency(currency));
};

export const getIsVpn2024Deal = (planName: PLANS, coupon: string | undefined) => {
    return (
        planName === PLANS.VPN2024 &&
        [COUPON_CODES.MARCHSAVINGS24, COUPON_CODES.HONEYPROTONSAVINGS, COUPON_CODES.PREMIUM_DEAL].includes(
            coupon as COUPON_CODES
        )
    );
};

export const getDefaultSelectedProductPlans = ({
    appName,
    plan,
    planIDs,
    plansMap,
    cycle,
}: {
    appName: ProductParam;
    plan?: string;
    planIDs: PlanIDs;
    cycle: CYCLE | undefined;
    plansMap: PlansMap;
}) => {
    let defaultB2CPlan = PLANS.MAIL;
    if (appName === APPS.PROTONVPN_SETTINGS) {
        defaultB2CPlan = getVPNPlanToUse({ plansMap, planIDs, cycle });
    } else if (appName === APPS.PROTONDRIVE) {
        defaultB2CPlan = PLANS.DRIVE;
    } else if (appName === APPS.PROTONPASS) {
        defaultB2CPlan = PLANS.PASS;
    } else if (appName === APPS.PROTONWALLET) {
        defaultB2CPlan = PLANS.WALLET;
    } else if (appName === APPS.PROTONLUMO) {
        defaultB2CPlan = PLANS.LUMO;
    }

    const matchingB2CPlan = [PLANS.MAIL, PLANS.VPN, /*PLANS.VPN2024, */ PLANS.DRIVE, PLANS.WALLET].find(
        (planName) => plan === planName || planIDs[planName]
    );
    const matchingB2BPlan = [PLANS.MAIL_PRO, PLANS.DRIVE_PRO].find(
        (planName) => plan === planName || planIDs[planName]
    );
    const defaultB2BPlan = PLANS.MAIL_PRO;
    return {
        [Audience.B2C]: matchingB2CPlan || defaultB2CPlan,
        [Audience.B2B]: matchingB2BPlan || defaultB2BPlan,
        [Audience.FAMILY]: PLANS.FAMILY,
    };
};
export type SelectedProductPlans = ReturnType<typeof getDefaultSelectedProductPlans>;

interface FreeSubscriptionResult {
    subscriptionExpiresSoon: false;
    renewDisabled: false;
    renewEnabled: true;
    expirationDate: null;
}

type SubscriptionResult = {
    renewDisabled: boolean;
    renewEnabled: boolean;
    planName: string;
} & (
    | {
          subscriptionExpiresSoon: true;
          expirationDate: number;
      }
    | {
          subscriptionExpiresSoon: false;
          expirationDate: null;
      }
);

export function subscriptionExpires(): FreeSubscriptionResult;
export function subscriptionExpires(subscription: undefined | null): FreeSubscriptionResult;
export function subscriptionExpires(subscription: FreeSubscription): FreeSubscriptionResult;
export function subscriptionExpires(subscription: SubscriptionModel | undefined): SubscriptionResult;
export function subscriptionExpires(subscription: SubscriptionModel): SubscriptionResult;
export function subscriptionExpires(
    subscription?: SubscriptionModel | FreeSubscription | null
): FreeSubscriptionResult | SubscriptionResult {
    if (!subscription || isFreeSubscription(subscription)) {
        return {
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        };
    }

    const latestSubscription = subscription.UpcomingSubscription ?? subscription;
    const renewDisabled = latestSubscription.Renew === Renew.Disabled;
    const renewEnabled = latestSubscription.Renew === Renew.Enabled;
    const subscriptionExpiresSoon = renewDisabled;

    const planName = latestSubscription.Plans?.[0]?.Title;

    if (subscriptionExpiresSoon) {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: latestSubscription.PeriodEnd,
        };
    } else {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: null,
        };
    }
}

export const getAutoCoupon = ({
    planIDs,
    cycle,
    coupon,
}: {
    planIDs: PlanIDs;
    cycle: CYCLE;
    coupon?: string | null;
}) => {
    if (!coupon && [PLANS.PASS_BUSINESS, PLANS.PASS_PRO].some((plan) => planIDs?.[plan])) {
        return COUPON_CODES.PASS_B2B_INTRO;
    }

    if (!coupon && [PLANS.DRIVE_BUSINESS].some((plan) => planIDs?.[plan])) {
        return COUPON_CODES.DRIVEB2BINTRO2024;
    }

    if (
        !coupon &&
        [PLANS.VPN2024].some((plan) => planIDs?.[plan]) &&
        [CYCLE.YEARLY, CYCLE.TWO_YEARS].includes(cycle as any)
    ) {
        return COUPON_CODES.VPN_INTRO_2024;
    }

    return coupon || undefined;
};

export function notHigherThanAvailableOnBackend(planIDs: PlanIDs, plansMap: PlansMap, cycle: CYCLE): CYCLE {
    const plan = getPlanFromIDs(planIDs, plansMap);
    if (!plan) {
        return cycle;
    }

    const availableCycles = Object.keys(plan.Pricing) as unknown as CYCLE[];
    const maxCycle = Math.max(...availableCycles) as CYCLE;
    return Math.min(cycle, maxCycle);
}

export const countriesWithStates = Object.freeze(['US', 'CA']);

export type BillingAddressStatus =
    | {
          valid: true;
          reason: undefined;
      }
    | {
          valid: false;
          reason: 'missingCountry' | 'missingState';
      };

export const BILLING_ADDRESS_VALID = Object.freeze({ valid: true, reason: undefined }) as BillingAddressStatus;

export function getBillingAddressStatus(billingAddress: BillingAddress): BillingAddressStatus {
    if (!billingAddress.CountryCode) {
        return { valid: false, reason: 'missingCountry' };
    }

    const isCountryWithState = countriesWithStates.includes(billingAddress.CountryCode);
    if (!isCountryWithState) {
        return BILLING_ADDRESS_VALID;
    }

    if (!billingAddress.State) {
        return { valid: false, reason: 'missingState' };
    }

    return BILLING_ADDRESS_VALID;
import { FREE_SUBSCRIPTION, PLANS } from '@proton/payments';
import { CYCLE } from '@proton/shared/lib/constants';
import { Renew } from '@proton/shared/lib/interfaces';
import { PLANS_MAP, subscriptionMock, upcomingSubscriptionMock } from '@proton/testing/data';

import {
    countriesWithStates,
    getBillingAddressStatus,
    notHigherThanAvailableOnBackend,
    subscriptionExpires,
} from './payment';

describe('subscriptionExpires()', () => {
    it('should handle the case when subscription is not loaded yet', () => {
        expect(subscriptionExpires()).toEqual({
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        });
    });

    it('should handle the case when subscription is free', () => {
        expect(subscriptionExpires(FREE_SUBSCRIPTION as any)).toEqual({
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        });
    });

    it('should handle non-expiring subscription', () => {
        expect(subscriptionExpires(subscriptionMock)).toEqual({
            subscriptionExpiresSoon: false,
            planName: 'Proton Unlimited',
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        });
    });

    it('should handle expiring subscription', () => {
        expect(
            subscriptionExpires({
                ...subscriptionMock,
                Renew: Renew.Disabled,
            })
        ).toEqual({
            subscriptionExpiresSoon: true,
            planName: 'Proton Unlimited',
            renewDisabled: true,
            renewEnabled: false,
            expirationDate: subscriptionMock.PeriodEnd,
        });
    });

    it('should handle the case when the upcoming subscription expires', () => {
        expect(
            subscriptionExpires({
                ...subscriptionMock,
                UpcomingSubscription: {
                    ...upcomingSubscriptionMock,
                    Renew: Renew.Disabled,
                },
            })
        ).toEqual({
            subscriptionExpiresSoon: true,
            planName: 'Proton Unlimited',
            renewDisabled: true,
            renewEnabled: false,
            expirationDate: upcomingSubscriptionMock.PeriodEnd,
        });
    });

    it('should handle the case when the upcoming subscription does not expire', () => {
        expect(
            subscriptionExpires({
                ...subscriptionMock,
                UpcomingSubscription: {
                    ...upcomingSubscriptionMock,
                    Renew: Renew.Enabled,
                },
            })
        ).toEqual({
            subscriptionExpiresSoon: false,
            planName: 'Proton Unlimited',
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        });
    });
});

describe('notHigherThanAvailableOnBackend', () => {
    it('should return current cycle if plan does not exist in the planIDs', () => {
        expect(notHigherThanAvailableOnBackend({}, PLANS_MAP, CYCLE.MONTHLY)).toEqual(CYCLE.MONTHLY);
    });

    it('should return current cycle if plan does not exist in the plansMap', () => {
        expect(notHigherThanAvailableOnBackend({ [PLANS.MAIL]: 1 }, {}, CYCLE.MONTHLY)).toEqual(CYCLE.MONTHLY);
    });

    it.each([CYCLE.MONTHLY, CYCLE.THIRTY, CYCLE.YEARLY, CYCLE.FIFTEEN, CYCLE.EIGHTEEN, CYCLE.TWO_YEARS, CYCLE.THIRTY])(
        'should return current cycle if it is not higher than available on backend',
        (cycle) => {
            expect(notHigherThanAvailableOnBackend({ [PLANS.VPN2024]: 1 }, PLANS_MAP, cycle)).toEqual(cycle);
        }
    );

    it.each([
        {
            plan: PLANS.MAIL,
            cycle: CYCLE.THIRTY,
            expected: CYCLE.TWO_YEARS,
        },
        {
            plan: PLANS.MAIL,
            cycle: CYCLE.TWO_YEARS,
            expected: CYCLE.TWO_YEARS,
        },
        {
            plan: PLANS.MAIL,
            cycle: CYCLE.YEARLY,
            expected: CYCLE.YEARLY,
        },
        {
            plan: PLANS.WALLET,
            cycle: CYCLE.TWO_YEARS,
            expected: CYCLE.YEARLY,
        },
        {
            plan: PLANS.WALLET,
            cycle: CYCLE.YEARLY,
            expected: CYCLE.YEARLY,
        },
    ])('should cap cycle if the backend does not have available higher cycles', ({ plan, cycle, expected }) => {
        expect(notHigherThanAvailableOnBackend({ [plan]: 1 }, PLANS_MAP, cycle)).toEqual(expected);
    });
});

describe('isBillingAddressValid', () => {
    it.each(['DE', 'FR', 'CH', 'GB'])(
        'should return true for regular countries without State condition - %s',
        (CountryCode) => {
            expect(getBillingAddressStatus({ CountryCode })).toEqual({ valid: true });
        }
    );

    it('should return false if CountryCode is not specified', () => {
        expect(getBillingAddressStatus({} as any)).toEqual({ valid: false, reason: 'missingCountry' });
        expect(getBillingAddressStatus({ CountryCode: '' })).toEqual({ valid: false, reason: 'missingCountry' });
        expect(getBillingAddressStatus({ CountryCode: null } as any)).toEqual({
            valid: false,
            reason: 'missingCountry',
        });
        expect(getBillingAddressStatus({ CountryCode: undefined } as any)).toEqual({
            valid: false,
            reason: 'missingCountry',
        });
    });

    it.each(countriesWithStates)(
        'should return false if CountryCode is specified but state is not - %s',
        (CountryCode) => {
            expect(getBillingAddressStatus({ CountryCode })).toEqual({ valid: false, reason: 'missingState' });
            expect(getBillingAddressStatus({ CountryCode, State: null })).toEqual({
                valid: false,
                reason: 'missingState',
            });
            expect(getBillingAddressStatus({ CountryCode, State: undefined })).toEqual({
                valid: false,
                reason: 'missingState',
            });
            expect(getBillingAddressStatus({ CountryCode, State: '' })).toEqual({
                valid: false,
                reason: 'missingState',
            });
        }
    );

    it('should return true if CountryCode and State are specified', () => {
        expect(getBillingAddressStatus({ CountryCode: 'US', State: 'AL' })).toEqual({ valid: true });
        expect(getBillingAddressStatus({ CountryCode: 'CA', State: 'NL' })).toEqual({ valid: true });
    });
});
